/* ===== module: formulas/decline.js ===== */
/* FORK v1.988: decline detection for estimated 1RM — the "1RM moving
   down" system (GitHub #376: "projected 1RM should be able to go down —
   but only rarely and conservatively").

   Pure functions only — no DOM, no state — so the unit suite can load
   this file alone (test role `fork-decline`). The engine hook lives in
   workout/progression.js (marked FORK v1.988); this file only answers
   one question from plain numbers:

     Given the per-session top-set e1RM estimates for one exercise,
     NEWEST FIRST, is the lifter's capacity in a sustained decline —
     and if so, what is their CURRENT capacity?

   Why this exists: the %1RM scheme's auto training max is the BEST
   same-zone e1RM ever logged, so after a layoff, an injury, or a slow
   detraining slide it keeps prescribing loads off a peak the lifter
   no longer has. #376 splits the numbers in two — the all-time best
   stays the record and never moves; only the WORKING basis follows
   current form. This module is the working-basis half: it never
   touches PRs, records, or the all-time best.

   Detection rules (conservative by construction — one bad day must
   never fire this):
   - Fewer than MIN_SESSIONS usable sessions: no opinion, no change.
   - Rule 1 (recent best vs trailing peak): the BEST e1RM of the last
     RECENT_WINDOW sessions sits at least DROP_PCT below the trailing
     peak (the best e1RM anywhere in the window the caller supplies).
     Best-of-recent (not latest, not mean) is deliberate: one good
     session inside the window proves the capacity is still there and
     resets the verdict — the same conservatism as #376's "last 3
     sessions, each ≥5% under" bar, stated from the other side.
   - Rule 2 (slow slide): the last TREND_SESSIONS sessions fall
     strictly, session over session, losing at least TREND_DROP_PCT in
     total. A slide of −1% a week never trips Rule 1's 5% bar against
     a best-of-3 that still contains last week's number; Rule 2 is
     what catches it. Strictly falling is required — one flat or up
     session breaks the slide.
   - Recovery is automatic and needs no state: the moment the recent
     best climbs back within DROP_PCT of the peak (or a new peak is
     set), the state reads not-declining again. Suggestions then climb
     back through the normal schemes — the "rebuild ramp" is just the
     ordinary engine running on an honest basis.

   Threshold grounding (#376 consultations): 1RM test–retest CV is
   3.3–5.4%, so a single session at −5% is pure noise — 5% against a
   best-of-3 is the smallest margin that means anything. Detraining
   research (Mujika & Padilla 2000) puts real loss at ~6% over 4–8
   weeks off and 10–16% over 12–20 weeks, so genuine declines clear
   the bar comfortably while noise does not.

   What the caller does with a decline (progression.js): the %1RM
   auto basis is capped at `capacity` (the recent best), stall/stage
   rewrites stand down, and the suggestion card carries a plain
   "Rebuilding" line with both numbers labelled. A manually entered
   training max is NEVER capped — it is the lifter's own number
   (#376: manual is sovereign). */

const FORK_DECLINE_MIN_SESSIONS = 3;   /* below this: no opinion */
const FORK_DECLINE_RECENT_WINDOW = 3; /* sessions in the "recent" best */
const FORK_DECLINE_DROP_PCT = 5;      /* Rule 1 margin, % below peak */
const FORK_DECLINE_TREND_SESSIONS = 4;/* Rule 2 window */
const FORK_DECLINE_TREND_DROP_PCT = 3;/* Rule 2 total slide, % */

/* forkDeclineState(series) -> {
     declining: boolean,
     via: 'recent' | 'trend' | null,   // which rule fired
     sessions: number,                // usable sessions seen
     peak: number,                    // trailing-peak e1RM (0 if none)
     recentBest: number,              // best e1RM of the recent window
     capacity: number,                // == recentBest; the working basis
     dropPct: number                  // (peak - recentBest) / peak * 100
   }
   `series` is newest-first e1RM estimates; non-positive / non-finite
   entries are dropped before any rule runs (a bodyweight or blank
   session is not evidence of anything). */
function forkDeclineState(series) {
  const s = (Array.isArray(series) ? series : [])
    .map(Number)
    .filter(v => Number.isFinite(v) && v > 0);
  const none = { declining: false, via: null, sessions: s.length, peak: 0, recentBest: 0, capacity: 0, dropPct: 0 };
  if (s.length < FORK_DECLINE_MIN_SESSIONS) return none;
  const peak = Math.max(...s);
  const recentBest = Math.max(...s.slice(0, FORK_DECLINE_RECENT_WINDOW));
  const dropPct = peak > 0 ? (peak - recentBest) / peak * 100 : 0;
  const out = { declining: false, via: null, sessions: s.length, peak, recentBest, capacity: recentBest, dropPct };
  /* Rule 1: recent best meaningfully under the trailing peak. */
  if (dropPct >= FORK_DECLINE_DROP_PCT) { out.declining = true; out.via = 'recent'; return out; }
  /* Rule 2: a strict session-over-session slide across the trend
     window (the array is newest-first, so a slide reads as strictly
     increasing values going back in time). */
  if (s.length >= FORK_DECLINE_TREND_SESSIONS) {
    const w = s.slice(0, FORK_DECLINE_TREND_SESSIONS);
    let strict = true;
    for (let i = 0; i + 1 < w.length; i++) { if (!(w[i] < w[i + 1])) { strict = false; break; } }
    const slidePct = w[w.length - 1] > 0 ? (w[w.length - 1] - w[0]) / w[w.length - 1] * 100 : 0;
    if (strict && slidePct >= FORK_DECLINE_TREND_DROP_PCT) { out.declining = true; out.via = 'trend'; out.dropPct = Math.max(dropPct, slidePct); }
  }
  return out;
}
